import hashlib
import json
from pathlib import Path

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, Output, StrInput
from lfx.schema.data import Data
from lfx.schema.message import Message
from lfx.utils.file_path_security import (
    component_file_access_scopes,
    enforce_local_file_access,
)


class OutlookMessageID(Component):
    display_name = "Outlook Message ID"
    description = (
        "Extracts the Outlook email ID and blocks repeat processing across "
        "workers using shared NFS claim files. Claims survive server restarts."
    )
    icon = "mail"
    name = "OutlookMessageID"

    inputs = [
        DataInput(
            name="webhook_data",
            display_name="Webhook JSON",
            required=True,
        ),
        StrInput(
            name="shared_directory",
            display_name="Shared NFS Directory",
            info=(
                "Absolute path to an existing shared NFS folder accessible "
                "to both workers. Claim files are stored here."
            ),
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="message_id",
            display_name="Message ID",
            method="extract_id",
        ),
    ]

    @staticmethod
    def as_dict(value):
        if isinstance(value, Data):
            value = value.data
        if isinstance(value, str):
            value = json.loads(value)
        if not isinstance(value, dict):
            raise ValueError("Expected a JSON object in the webhook payload.")
        return value

    def claim_email(self, account_id, message_id):
        directory_value = str(self.shared_directory or "").strip()
        if not directory_value:
            raise ValueError("Shared NFS Directory is required.")

        directory = Path(directory_value)
        if not directory.is_absolute():
            raise ValueError("Shared NFS Directory must be an absolute path.")

        # Preserve the platform's file-access restrictions.
        scope_ids = component_file_access_scopes(self)
        directory = enforce_local_file_access(
            directory,
            scope_ids=scope_ids,
        )

        # Require an existing directory to avoid silently creating a local
        # fallback folder when the intended shared directory is unavailable.
        if not directory.is_dir():
            raise ValueError(
                "Shared NFS Directory is unavailable or is not a directory."
            )

        key = hashlib.sha256(
            json.dumps(
                [account_id, message_id],
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()

        claim_path = enforce_local_file_access(
            directory / f"outlook_email_{key}.json",
            scope_ids=scope_ids,
        )

        claim_content = json.dumps(
            {
                "connected_account_id": account_id,
                "message_id": message_id,
            },
            ensure_ascii=False,
        )

        try:
            # Exclusive creation: only one worker can create this file.
            claim_file = claim_path.open("x", encoding="utf-8")
        except FileExistsError:
            return False
        except OSError as exc:
            raise ValueError(
                "Cannot create the shared NFS claim file. Processing stopped."
            ) from exc

        try:
            with claim_file:
                claim_file.write(claim_content)
        except OSError as exc:
            # Keep the claim if writing fails; do not allow another worker
            # to proceed with the same email automatically.
            raise ValueError(
                "Cannot write the shared NFS claim file. "
                "Processing stopped; the claim may require manual cleanup."
            ) from exc

        return True

    def extract_id(self) -> Message:
        event = self.as_dict(self.webhook_data)
        if event.get("type") != "composio.trigger.message":
            raise ValueError("No Composio event received. Test with a new email.")

        metadata = self.as_dict(event.get("metadata", {}))
        if metadata.get("trigger_slug") != "OUTLOOK_MESSAGE_TRIGGER":
            raise ValueError("Expected an Outlook message trigger.")

        account_id = metadata.get("connected_account_id")
        if not isinstance(account_id, str) or not account_id.strip():
            raise ValueError("Connected account ID is missing.")

        payload = self.as_dict(event.get("data", {}))
        if payload.get("event_type") != "message.created":
            raise ValueError("Expected a message.created event.")

        message_id = payload.get("id")
        if not isinstance(message_id, str) or not message_id.strip():
            raise ValueError(
                "Outlook message ID is missing from event.data.id."
            )

        account_id, message_id = account_id.strip(), message_id.strip()

        # Construct the output before claiming to avoid claiming an email
        # when local output construction fails.
        result = Message(text=message_id)

        if not self.claim_email(account_id, message_id):
            self.status = (
                "DUPLICATE_SKIPPED: email already claimed in shared NFS."
            )
            self.stop("message_id")
            # Never send an empty ID downstream.
            raise ValueError(self.status)

        self.status = "NEW_EMAIL: message ID extracted; processing allowed."
        return result

import json
import re
from html.parser import HTMLParser

from lfx.custom.custom_component.component import Component
from lfx.io import DataFrameInput, DataInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


class EmailInputBuilder(Component):
    display_name = "Email Input Builder"
    description = "Cleans one Outlook email and preserves its identifiers for classification and thread handling."
    icon = "mail"
    name = "EmailInputBuilder"

    inputs = [
        DataFrameInput(name="email_table", display_name="Outlook Email", required=True),
        DataInput(name="webhook_context", display_name="Webhook Context", required=True),
    ]
    outputs = [
        Output(name="email_context", display_name="Email Context", method="build_context", group_outputs=True),
        Output(name="llm_input", display_name="LLM Input", method="build_llm_input", group_outputs=True),
    ]

    @staticmethod
    def _object(value):
        if isinstance(value, Data):
            value = value.data
        if isinstance(value, str):
            if not value.strip():
                return {}
            value = json.loads(value)
        return value if isinstance(value, dict) else {}

    @staticmethod
    def _text(value):
        return value.strip() if isinstance(value, str) else ""

    def _address(self, value):
        address = self._object(self._object(value).get("emailAddress"))
        return {"email": self._text(address.get("address")), "name": self._text(address.get("name"))}

    def _addresses(self, value):
        if isinstance(value, str):
            value = json.loads(value)
        return [self._address(item) for item in value] if isinstance(value, list) else []

    @staticmethod
    def _html_text(content):
        class EmailHTMLParser(HTMLParser):
            def __init__(self):
                super().__init__(convert_charrefs=True)
                self.parts = []
                self.hidden = []
                self.blocks = {"p", "div", "br", "li", "tr", "table", "blockquote", "h1", "h2", "h3", "hr"}

            def handle_starttag(self, tag, attrs):
                if tag in {"head", "script", "style", "template"}:
                    self.hidden.append(tag)
                if not self.hidden:
                    if tag in self.blocks:
                        self.parts.append("\n")
                    elif tag in {"td", "th"}:
                        self.parts.append("\t")
                    elif tag == "img":
                        alt = dict(attrs).get("alt")
                        if alt:
                            self.parts.append(" " + alt + " ")

            def handle_startendtag(self, tag, attrs):
                self.handle_starttag(tag, attrs)
                self.handle_endtag(tag)

            def handle_endtag(self, tag):
                if tag in self.hidden:
                    index = len(self.hidden) - 1 - self.hidden[::-1].index(tag)
                    del self.hidden[index:]
                elif not self.hidden and tag in self.blocks:
                    self.parts.append("\n")

            def handle_data(self, value):
                if not self.hidden:
                    self.parts.append(value)

        parser = EmailHTMLParser()
        parser.feed(content)
        parser.close()
        return "".join(parser.parts)

    def _prepare(self):
        rows = self.email_table.to_dict(orient="records")
        if len(rows) != 1:
            raise ValueError("Outlook Email must contain exactly one email row.")
        row = rows[0]
        event = self._object(self.webhook_context)
        metadata = self._object(event.get("metadata"))
        event_data = self._object(event.get("data"))
        account_id = self._text(metadata.get("connected_account_id"))
        message_id = self._text(row.get("id"))
        if not account_id or not message_id:
            raise ValueError("Connected account ID and Outlook message ID are required.")
        if event_data.get("id") != message_id:
            raise ValueError("Outlook email ID does not match the incoming webhook email ID.")
        body = self._object(row.get("body"))
        content = body.get("content")
        if not isinstance(content, str):
            raise ValueError("Full email body is missing. Fetch body.content; do not use bodyPreview.")
        content_type = self._text(body.get("contentType")).lower()
        if content_type not in {"html", "text"}:
            raise ValueError("Email body.contentType must be html or text.")
        body_text = self._html_text(content) if content_type == "html" else content
        body_text = body_text.replace("\r\n", "\n").replace("\r", "\n").replace("\xa0", " ")
        body_text = "\n".join(re.sub(r"[ \t]+", " ", line).strip() for line in body_text.split("\n"))
        body_text = re.sub(r"\n{3,}", "\n\n", body_text).strip()
        sender = self._address(row.get("from"))
        flags = []
        if not sender["email"]:
            flags.append("SENDER_EMAIL_MISSING")
        conversation_id = self._text(row.get("conversationId"))
        if not conversation_id:
            flags.append("CONVERSATION_ID_MISSING")
        if not body_text:
            flags.append("EMPTY_BODY")
        attachments = row.get("hasAttachments")
        has_attachments = str(attachments).lower() == "true"
        if has_attachments:
            flags.append("ATTACHMENTS_NOT_RETRIEVED")
        return {
            "connected_account_id": account_id,
            "event_id": self._text(event.get("id")),
            "message_id": message_id,
            "conversation_id": conversation_id,
            "internet_message_id": self._text(row.get("internetMessageId")),
            "sender_email": sender["email"],
            "sender_name": sender["name"],
            "sent_by": self._address(row.get("sender")),
            "to_recipients": self._addresses(row.get("toRecipients")),
            "cc_recipients": self._addresses(row.get("ccRecipients")),
            "reply_to": self._addresses(row.get("replyTo")),
            "subject": self._text(row.get("subject")),
            "body_text": body_text,
            "body_content_type": content_type,
            "received_at": self._text(row.get("receivedDateTime")),
            "sent_at": self._text(row.get("sentDateTime")),
            "has_attachments": has_attachments,
            "thread_history_loaded": False,
            "flags": flags,
        }

    def build_context(self) -> Data:
        result = self._prepare()
        self.status = "Email prepared. " + (", ".join(result["flags"]) or "No preparation flags.")
        return Data(data=result)

    def build_llm_input(self) -> Message:
        result = self._prepare()
        fields = ["message_id", "conversation_id", "sender_email", "sender_name", "subject", "body_text", "received_at", "has_attachments", "thread_history_loaded", "flags"]
        return Message(text=json.dumps({key: result[key] for key in fields}, ensure_ascii=False))

