class EmailRelevanceGate(Component):
    display_name = "Email Relevance Gate"
    description = "Validates the relevance decision and passes only CONTINUE emails downstream."
    icon = "filter"
    name = "EmailRelevanceGate"

    inputs = [
        MessageTextInput(name="classification", display_name="Classification", required=True),
        DataInput(name="email_context", display_name="Email Context", required=True),
    ]
    outputs = [
        Output(name="accepted_email", display_name="Accepted Email", method="route_email"),
    ]

    def route_email(self) -> Data:
        raw = self.classification
        if isinstance(raw, Message):
            raw = raw.text
        if not isinstance(raw, str) or not raw.strip():
            raise ValueError("CLASSIFICATION_INVALID: classifier response is empty.")
        try:
            result = json.loads(raw.strip())
        except json.JSONDecodeError as exc:
            raise ValueError("CLASSIFICATION_INVALID: expected a single JSON object. Retry the classifier.") from exc
        if not isinstance(result, dict) or set(result) != {"category", "decision", "reason"}:
            raise ValueError("CLASSIFICATION_INVALID: expected exactly category, decision and reason.")
        routes = {
            "CUSTOMER_SERVICE": "CONTINUE",
            "UNCERTAIN": "CONTINUE",
            "PROMOTION": "STOP",
            "SPAM": "STOP",
            "AUTOMATED_NOTIFICATION": "STOP",
            "UNRELATED": "STOP",
        }
        category, decision, reason = result["category"], result["decision"], result["reason"]
        if not isinstance(category, str) or category not in routes:
            raise ValueError("CLASSIFICATION_INVALID: unknown category.")
        if not isinstance(decision, str) or decision != routes[category]:
            raise ValueError("CLASSIFICATION_INVALID: category and decision conflict.")
        if not isinstance(reason, str) or not reason.strip():
            raise ValueError("CLASSIFICATION_INVALID: reason must be non-empty text.")
        context = self.email_context
        if isinstance(context, Data):
            context = context.data
        if not isinstance(context, dict):
            raise ValueError("EMAIL_CONTEXT_INVALID: connect Email Input Builder's Email Context output.")
        if not all(isinstance(context.get(key), str) and context[key].strip()
                   for key in ("connected_account_id", "message_id")):
            raise ValueError("EMAIL_CONTEXT_INVALID: account ID and message ID are required.")
        if decision == "STOP":
            # Abort explicitly to prevent hosted versions from forwarding empty Data
            # after stop(). This makes a filtered run appear stopped/failed in logs.
            self.status = "EMAIL_FILTERED: " + category
            self.stop("accepted_email")
            raise ValueError(self.status)
        output = dict(context)
        output["relevance"] = {
            "category": category,
            "decision": decision,
            "reason": reason.strip(),
        }
        self.status = "CONTINUE: " + category
        return Data(data=output)

