class OutlookThreadLookupInput(Component):
    display_name = "Outlook Thread Lookup Input"
    description = (
        "Extracts the conversation ID from an accepted email so Outlook "
        "thread history can be retrieved."
    )
    icon = "mail-search"
    name = "OutlookThreadLookupInput"

    inputs = [
        DataInput(
            name="accepted_email",
            display_name="Accepted Email",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="conversation_id",
            display_name="Conversation ID",
            method="build_conversation_id",
            group_outputs=True,
        ),
        Output(
            name="thread_filter",
            display_name="Thread Filter",
            method="build_thread_filter",
            group_outputs=True,
        ),
    ]

    def _context(self):
        value = self.accepted_email

        if isinstance(value, Data):
            value = value.data

        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError as exc:
                raise ValueError(
                    "ACCEPTED_EMAIL_INVALID: expected a JSON object."
                ) from exc

        if not isinstance(value, dict):
            raise ValueError(
                "ACCEPTED_EMAIL_INVALID: connect Email Relevance Gate's "
                "Accepted Email output."
            )

        message_id = value.get("message_id")

        if not isinstance(message_id, str) or not message_id.strip():
            raise ValueError(
                "ACCEPTED_EMAIL_INVALID: message_id is required."
            )

        relevance = value.get("relevance")

        if (
            not isinstance(relevance, dict)
            or relevance.get("decision") != "CONTINUE"
        ):
            raise ValueError(
                "ACCEPTED_EMAIL_INVALID: only CONTINUE emails can load "
                "thread context."
            )

        return value

    def build_conversation_id(self) -> Message:
        context = self._context()
        conversation_id = context.get("conversation_id")

        if isinstance(conversation_id, str) and conversation_id.strip():
            self.status = (
                "THREAD_LOOKUP_READY: conversation ID extracted."
            )

            return Message(
                text=conversation_id.strip()
            )

        self.status = (
            "THREAD_LOOKUP_GAP: conversation ID missing; history will be "
            "marked unavailable."
        )

        return Message(
            text="__NO_CONVERSATION_ID__"
        )

    def build_thread_filter(self) -> Message:
        context = self._context()
        conversation_id = context.get("conversation_id")

        if not isinstance(conversation_id, str) or not conversation_id.strip():
            raise ValueError(
                "THREAD_LOOKUP_UNAVAILABLE: conversation_id is missing."
            )

        conversation_id = (
            conversation_id
            .strip()
            .replace("'", "''")
        )

        self.status = (
            "THREAD_LOOKUP_READY: Outlook conversation filter prepared."
        )

        return Message(
            text=f"conversationId eq '{conversation_id}'"
        )

