class HistoricalMessageQueueBuilder(Component):
    display_name = "Historical Msg Queue Builder"
    description = (
        "Combines Inbox and Sent Items thread-query results into one queue "
        "of historical Outlook message IDs, excluding the current inbound email."
    )
    icon = "list"
    name = "HistoricalMessageQueueBuilder"

    inputs = [
        DataInput(
            name="accepted_email",
            display_name="Accepted Email",
            required=True,
        ),
        DataFrameInput(
            name="inbox_messages",
            display_name="Inbox Query Results",
            required=True,
        ),
        DataFrameInput(
            name="sent_messages",
            display_name="Sent Query Results",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="message_queue",
            display_name="Historical Message Queue",
            method="build_queue",
        ),
    ]

    @staticmethod
    def _object(value):
        if isinstance(value, Data):
            value = value.data

        if isinstance(value, str):
            if not value.strip():
                return {}

            try:
                value = json.loads(value)
            except json.JSONDecodeError:
                return {}

        return value if isinstance(value, dict) else {}

    @staticmethod
    def _text(value):
        return value.strip() if isinstance(value, str) else ""

    @classmethod
    def _query_messages(cls, value):
        if value is None:
            return []

        if hasattr(value, "to_dict"):
            records = value.to_dict(orient="records")
        elif isinstance(value, list):
            records = value
        elif isinstance(value, dict):
            records = [value]
        else:
            return []

        messages = []

        for record in records:
            if not isinstance(record, dict):
                continue

            nested = record.get("value")

            if isinstance(nested, str):
                try:
                    nested = json.loads(nested)
                except json.JSONDecodeError:
                    nested = None

            if isinstance(nested, list):
                messages.extend(
                    item
                    for item in nested
                    if isinstance(item, dict)
                )
                continue

            # Also tolerate an already-flattened message row.
            if record.get("id"):
                messages.append(record)

        return messages

    def _accepted_context(self):
        value = self.accepted_email

        if isinstance(value, Data):
            value = value.data

        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError as exc:
                raise ValueError(
                    "ACCEPTED_EMAIL_INVALID: expected a JSON object."
                ) from exc

        if not isinstance(value, dict):
            raise ValueError(
                "ACCEPTED_EMAIL_INVALID: connect Email Relevance Gate's "
                "Accepted Email output."
            )

        message_id = self._text(value.get("message_id"))
        conversation_id = self._text(value.get("conversation_id"))

        if not message_id:
            raise ValueError(
                "ACCEPTED_EMAIL_INVALID: message_id is required."
            )

        if not conversation_id:
            raise ValueError(
                "THREAD_HISTORY_UNAVAILABLE: conversation_id is required."
            )

        return value

    def build_queue(self) -> DataFrame:
        context = self._accepted_context()

        current_message_id = self._text(
            context.get("message_id")
        )

        conversation_id = self._text(
            context.get("conversation_id")
        )

        queue = []
        seen_ids = set()

        sources = [
            (
                "inbox",
                self._query_messages(self.inbox_messages),
            ),
            (
                "sentitems",
                self._query_messages(self.sent_messages),
            ),
        ]

        for source_folder, messages in sources:
            for message in messages:
                message_id = self._text(
                    message.get("id")
                )

                message_conversation_id = self._text(
                    message.get("conversationId")
                )

                if not message_id:
                    continue

                # Only keep messages from the expected Outlook conversation.
                if message_conversation_id != conversation_id:
                    continue

                # Current message already has its full body from the
                # initial Get Email Message node.
                if message_id == current_message_id:
                    continue

                if message_id in seen_ids:
                    continue

                seen_ids.add(message_id)

                queue.append(
                    {
                        "message_id": message_id,
                        "conversation_id": message_conversation_id,
                        "source_folder": source_folder,
                        "subject": self._text(
                            message.get("subject")
                        ),
                        "received_at": self._text(
                            message.get("receivedDateTime")
                        ),
                        "sent_at": self._text(
                            message.get("sentDateTime")
                        ),
                    }
                )

        queue.sort(
            key=lambda item: (
                item.get("sent_at")
                or item.get("received_at")
                or ""
            )
        )

        for index, item in enumerate(queue, start=1):
            item["sequence"] = index

        self.status = (
            f"THREAD_HISTORY_QUEUE_READY: "
            f"{len(queue)} historical messages queued."
        )

        columns = [
            "sequence",
            "message_id",
            "conversation_id",
            "source_folder",
            "subject",
            "received_at",
            "sent_at",
        ]

        return DataFrame(
            queue,
            columns=columns,
        )

