class OutlookThreadContextBuilder(Component):
    display_name = "Outlook Thread Context Builder"
    description = (
        "Combines the current accepted email with fully fetched historical "
        "Outlook messages into one chronological thread context."
    )
    icon = "messages-square"
    name = "OutlookThreadContextBuilder"

    inputs = [
        DataInput(
            name="accepted_email",
            display_name="Accepted Email",
            required=True,
        ),
        DataFrameInput(
            name="historical_messages",
            display_name="Historical Messages",
            required=True,
        ),
        DataFrameInput(
            name="message_queue",
            display_name="Message Queue",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="thread_context",
            display_name="Thread Context",
            method="build_thread_context",
            group_outputs=True,
        ),
        Output(
            name="llm_input",
            display_name="LLM Input",
            method="build_llm_input",
            group_outputs=True,
        ),
    ]

    @staticmethod
    def _text(value):
        return value.strip() if isinstance(value, str) else ""

    @staticmethod
    def _dict(value):
        if isinstance(value, Data):
            value = value.data

        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError:
                return {}

        return value if isinstance(value, dict) else {}

    @classmethod
    def _rows(cls, value):
        if value is None:
            return []

        if isinstance(value, DataFrame):
            records = value.to_dict(orient="records")

        elif hasattr(value, "to_dict"):
            try:
                records = value.to_dict(orient="records")
            except Exception:
                records = []

        elif isinstance(value, list):
            records = value

        elif isinstance(value, dict):
            records = [value]

        else:
            return []

        output = []

        for item in records:
            if isinstance(item, Data):
                item = item.data

            if not isinstance(item, dict):
                continue

            # Loop → Done may return Outlook results wrapped as:
            # {"text": "[{'id': ..., 'body': {...}, ...}]"}
            text_value = item.get("text")

            if isinstance(text_value, str) and text_value.strip():
                parsed = None

                try:
                    parsed = json.loads(text_value)
                except Exception:
                    try:
                        parsed = ast.literal_eval(text_value)
                    except Exception:
                        parsed = None

                if isinstance(parsed, list):
                    output.extend(
                        row
                        for row in parsed
                        if isinstance(row, dict)
                    )
                    continue

                if isinstance(parsed, dict):
                    output.append(parsed)
                    continue

            output.append(item)

        return output

    @staticmethod
    def _strip_quoted_text(value):
        """
        Removes quoted reply history from already-plain-text email bodies.
        Used especially for the current inbound email, whose body_text has
        already been converted from HTML earlier in the flow.
        """
        if not isinstance(value, str) or not value.strip():
            return ""

        text = (
            value
            .replace("\r\n", "\n")
            .replace("\r", "\n")
        )

        cut_points = []

        # Gmail-style:
        # On Wed, 9 Sep 2026 at ... wrote:
        gmail_match = re.search(
            r"(?im)^\s*On .{1,500} wrote:\s*$",
            text,
        )

        if gmail_match:
            cut_points.append(
                gmail_match.start()
            )

        # Common original-message separator.
        original_match = re.search(
            r"(?im)^\s*-{2,}\s*Original Message\s*-{2,}\s*$",
            text,
        )

        if original_match:
            cut_points.append(
                original_match.start()
            )

        # Outlook-style plain text reply header.
        outlook_match = re.search(
            r"(?ims)"
            r"^\s*From:\s+.+?"
            r"\n\s*Sent:\s+.+?"
            r"\n\s*To:\s+.+?"
            r"\n\s*Subject:\s+.+?$",
            text,
        )

        if outlook_match:
            cut_points.append(
                outlook_match.start()
            )

        if cut_points:
            text = text[
                :min(cut_points)
            ]

        # Remove leading quote markers if present.
        text = re.sub(
            r"(?m)^\s*>+\s?",
            "",
            text,
        )

        text = re.sub(
            r"[ \t]+",
            " ",
            text,
        )

        text = re.sub(
            r"\n\s*\n+",
            "\n\n",
            text,
        )

        return text.strip()

    @classmethod
    def _clean_html(cls, value):
        """
        Converts Outlook/Gmail HTML to clean plain text while removing
        quoted reply history before HTML tags are stripped.
        """
        if not isinstance(value, str) or not value.strip():
            return ""

        # Cut quoted/replied content at the beginning of the
        # containing HTML element so we do not leave partial
        # tags such as "<div" behind.
        quote_patterns = [
            r'(?is)<div[^>]*class=["\'][^"\']*gmail_quote[^"\']*["\'][^>]*>',
            r'(?is)<div[^>]*class=["\'][^"\']*x_gmail_quote[^"\']*["\'][^>]*>',
            r'(?is)<div[^>]*id=["\']divrplyfwdmsg["\'][^>]*>',
            r'(?is)<blockquote\b[^>]*>',
        ]

        cut_points = []

        for pattern in quote_patterns:
            match = re.search(pattern, value)

            if match:
                cut_points.append(
                    match.start()
                )

        if cut_points:
            value = value[
                :min(cut_points)
            ]

        # Remove script/style content.
        value = re.sub(
            r"(?is)<(script|style).*?>.*?</\1>",
            " ",
            value,
        )

        # Preserve useful line breaks.
        value = re.sub(
            r"(?i)<br\s*/?>",
            "\n",
            value,
        )

        value = re.sub(
            r"(?i)</p\s*>",
            "\n",
            value,
        )

        value = re.sub(
            r"(?i)</div\s*>",
            "\n",
            value,
        )

        # Remove remaining HTML tags.
        value = re.sub(
            r"(?s)<[^>]+>",
            " ",
            value,
        )

        value = html.unescape(
            value
        )

        value = re.sub(
            r"[ \t]+",
            " ",
            value,
        )

        value = re.sub(
            r"\n\s*\n+",
            "\n\n",
            value,
        )

        # Final text-level fallback.
        return cls._strip_quoted_text(
            value
        )

    @classmethod
    def _extract_email(cls, value):
        if not isinstance(value, dict):
            return ""

        email = (
            value.get("emailAddress")
            or value.get("email_address")
            or value
        )

        if isinstance(email, dict):
            return cls._text(
                email.get("address")
            )

        return ""

    @classmethod
    def _normalize_outlook_row(cls, row):
        if not isinstance(row, dict):
            return {}

        # Tolerate wrapper structures from tool output.
        for key in (
            "data",
            "response",
            "message",
        ):
            nested = row.get(
                key
            )

            if isinstance(
                nested,
                dict,
            ):
                if (
                    nested.get("id")
                    or nested.get("message_id")
                    or nested.get("conversationId")
                ):
                    row = nested
                    break

        message_id = cls._text(
            row.get("id")
            or row.get("message_id")
        )

        conversation_id = cls._text(
            row.get("conversationId")
            or row.get("conversation_id")
        )

        body = row.get(
            "body"
        )

        if isinstance(
            body,
            dict,
        ):
            body_content = (
                body.get("content")
                or ""
            )
        else:
            body_content = (
                body
                or ""
            )

        body_text = cls._clean_html(
            body_content
        )

        sender_obj = (
            row.get("from")
            or row.get("sender")
            or {}
        )

        sender_email = cls._extract_email(
            sender_obj
        )

        return {
            "message_id": message_id,
            "conversation_id": conversation_id,
            "subject": cls._text(
                row.get("subject")
            ),
            "sender_email": sender_email,
            "body_text": body_text,
            "received_at": cls._text(
                row.get("receivedDateTime")
                or row.get("received_at")
            ),
            "sent_at": cls._text(
                row.get("sentDateTime")
                or row.get("sent_at")
            ),
        }

    def _build(self):
        current = self._dict(
            self.accepted_email
        )

        if not current:
            raise ValueError(
                "ACCEPTED_EMAIL_INVALID: accepted email is required."
            )

        current_message_id = self._text(
            current.get(
                "message_id"
            )
        )

        conversation_id = self._text(
            current.get(
                "conversation_id"
            )
        )

        if not current_message_id:
            raise ValueError(
                "ACCEPTED_EMAIL_INVALID: message_id is required."
            )

        queue_rows = self._rows(
            self.message_queue
        )

        queue_by_id = {}

        for row in queue_rows:
            message_id = self._text(
                row.get(
                    "message_id"
                )
            )

            if message_id:
                queue_by_id[
                    message_id
                ] = row

        history = []

        for row in self._rows(
            self.historical_messages
        ):
            message = (
                self._normalize_outlook_row(
                    row
                )
            )

            message_id = message.get(
                "message_id"
            )

            if not message_id:
                continue

            # Current triggering message must never be treated as history.
            if (
                message_id
                == current_message_id
            ):
                continue

            metadata = queue_by_id.get(
                message_id,
                {},
            )

            source_folder = self._text(
                metadata.get(
                    "source_folder"
                )
            )

            if (
                source_folder
                == "sentitems"
            ):
                direction = (
                    "OUTBOUND_SUPPORT"
                )
            else:
                direction = (
                    "INBOUND"
                )

            message.update(
                {
                    "sequence": metadata.get(
                        "sequence"
                    ),
                    "source_folder": source_folder,
                    "direction": direction,
                    "is_current": False,
                }
            )

            history.append(
                message
            )

        history.sort(
            key=lambda item: (
                item.get("sent_at")
                or item.get(
                    "received_at"
                )
                or ""
            )
        )

        current_message = {
            "message_id": (
                current_message_id
            ),
            "conversation_id": (
                conversation_id
            ),
            "subject": self._text(
                current.get(
                    "subject"
                )
            ),
            "sender_email": self._text(
                current.get(
                    "sender_email"
                )
            ),
            "body_text": (
                self._strip_quoted_text(
                    current.get(
                        "body_text"
                    )
                )
            ),
            "received_at": self._text(
                current.get(
                    "received_at"
                )
            ),
            "sent_at": self._text(
                current.get(
                    "sent_at"
                )
            ),
            "source_folder": "inbox",
            "direction": "CURRENT_INBOUND",
            "is_current": True,
        }

        messages = (
            history
            + [current_message]
        )

        missing_body_count = sum(
            1
            for item in history
            if not item.get(
                "body_text"
            )
        )

        flags = list(
            current.get(
                "flags"
            )
            or []
        )

        if missing_body_count:
            flags.append(
                f"THREAD_MESSAGES_WITHOUT_BODY:"
                f"{missing_body_count}"
            )

        history_status = (
            "LOADED"
            if history
            else "NO_HISTORY"
        )

        if missing_body_count:
            history_status = (
                "PARTIAL"
            )

        result = dict(
            current
        )

        result.update(
            {   
                "body_text": current_message["body_text"],
                "thread_history_loaded": True,
                "history_status": history_status,
                "prior_message_count": len(
                    history
                ),
                "thread_message_count": len(
                    messages
                ),
                "messages": messages,
                "flags": flags,
            }
        )

        return result

    def build_thread_context(
        self,
    ) -> Data:
        result = self._build()

        self.status = (
            f"THREAD_CONTEXT_READY: "
            f"{result['prior_message_count']} historical "
            f"message(s) loaded."
        )

        return Data(
            data=result
        )

    def build_llm_input(
        self,
    ) -> Message:
        result = self._build()

        payload = {
            "current_email": {
                "message_id": result.get(
                    "message_id"
                ),
                "subject": result.get(
                    "subject"
                ),
                "sender_email": result.get(
                    "sender_email"
                ),
                "body_text": (
                    self._strip_quoted_text(
                        result.get(
                            "body_text"
                        )
                    )
                ),
                "received_at": result.get(
                    "received_at"
                ),
            },
            "thread": result.get(
                "messages",
                [],
            ),
            "thread_metadata": {
                "conversation_id": result.get(
                    "conversation_id"
                ),
                "prior_message_count": result.get(
                    "prior_message_count"
                ),
                "history_status": result.get(
                    "history_status"
                ),
                "flags": result.get(
                    "flags",
                    [],
                ),
            },
        }

        return Message(
            text=json.dumps(
                payload,
                ensure_ascii=False,
            )
        )

from __future__ import annotations

import json
from typing import Any

from fastmcp import Client
from fastmcp.client.transports import StreamableHttpTransport
from langflow.custom import Component
from langflow.io import (
    DataInput,
    IntInput,
    MessageTextInput,
    Output,
    SecretStrInput,
    StrInput,
)
from langflow.schema import Message


class CompanyKnowledgeAgent(Component):
    display_name = "Company Knowledge Agent"
    description = (
        "Calls CompanyKnowledgeAgent directly using a persistent session ID "
        "and returns the response for downstream processing."
    )
    icon = "Bot"
    name = "CompanyKnowledgeAgent"

    inputs = [
        DataInput(
            name="email_data",
            display_name="Current Email",
            required=True,
        ),
        MessageTextInput(
            name="session_id",
            display_name="Session ID",
            required=True,
        ),
        StrInput(
            name="knowledge_service_url",
            display_name="Knowledge Service URL",
            value="https://example.invalid/company-knowledge",
            required=True,
        ),
        SecretStrInput(
            name="knowledge_service_api_key",
            display_name="Knowledge Service API Key",
            required=True,
        ),
        StrInput(
            name="extra_params",
            display_name="x-extra-params",
            value="",
            required=False,
            advanced=True,
        ),
        IntInput(
            name="timeout",
            display_name="Timeout Seconds",
            value=300,
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="evidence",
            display_name="Company Knowledge Evidence",
            method="call_company-knowledge",
        ),
    ]

    async def call_company-knowledge(self) -> Message:
        raw_result, answer = await self._get_result()

        if self._is_error(raw_result):
            raise ValueError(
                answer
                or "CompanyKnowledgeAgent returned an MCP tool error."
            )

        if not answer:
            raise ValueError(
                "CompanyKnowledgeAgent returned an empty response."
            )

        return Message(
            text=answer,
            sender="Machine",
            sender_name="CompanyKnowledgeAgent",
        )

    async def _get_result(
        self,
    ) -> tuple[dict[str, Any], str]:

        question = self._normalise_email_data(
            self.email_data
        )

        if not question:
            raise ValueError(
                "Current Email cannot be empty."
            )

        session_id = self._normalise_text(
            self.session_id
        )

        if not session_id:
            raise ValueError(
                "Session ID cannot be empty."
            )

        knowledge_service_url = str(
            self.knowledge_service_url or ""
        ).strip()

        if not knowledge_service_url:
            raise ValueError(
                "Knowledge Service URL is required."
            )

        api_key = self._normalise_secret(
            self.knowledge_service_api_key
        )

        if not api_key:
            raise ValueError(
                "MCP API key is required."
            )

        extra_params = str(
            self.extra_params or ""
        ).strip()

        cache_key = (
            question,
            session_id,
            knowledge_service_url,
            extra_params,
            int(self.timeout),
        )

        if (
            getattr(
                self,
                "_cached_request_key",
                None,
            )
            == cache_key
            and hasattr(
                self,
                "_cached_raw_result",
            )
        ):
            return (
                self._cached_raw_result,
                self._cached_answer,
            )

        headers: dict[str, str] = {
            "Authorization": f"Bearer {api_key}",
            "x-session-id": session_id,
        }

        if (
            extra_params
            and extra_params != "{}"
        ):
            try:
                parsed_extra_params = json.loads(
                    extra_params
                )

            except json.JSONDecodeError as exc:
                raise ValueError(
                    "x-extra-params must be valid JSON."
                ) from exc

            if parsed_extra_params:
                headers[
                    "x-extra-params"
                ] = json.dumps(
                    parsed_extra_params,
                    ensure_ascii=False,
                    separators=(",", ":"),
                )

        transport = StreamableHttpTransport(
            url=knowledge_service_url,
            headers=headers,
        )

        try:
            async with Client(
                transport,
                auto_initialize=False,
                timeout=float(
                    self.timeout
                ),
            ) as client:

                await client.initialize(
                    timeout=float(
                        self.timeout
                    )
                )

                result = await client.call_tool_mcp(
                    "CompanyKnowledgeAgent",
                    {
                        "question": question,
                    },
                    timeout=float(
                        self.timeout
                    ),
                )

        except Exception as exc:
            raise ValueError(
                f"Failed to call CompanyKnowledgeAgent: {exc}"
            ) from exc

        raw_result = self._to_dict(
            result
        )

        answer = self._extract_exact_text(
            raw_result
        )

        self._cached_request_key = cache_key
        self._cached_raw_result = raw_result
        self._cached_answer = answer

        return (
            raw_result,
            answer,
        )

    @staticmethod
    def _is_error(
        raw_result: dict[str, Any],
    ) -> bool:
        return bool(
            raw_result.get(
                "isError",
                raw_result.get(
                    "is_error",
                    False,
                ),
            )
        )

    @staticmethod
    def _normalise_email_data(
        value: Any,
    ) -> str:

        if value is None:
            return ""

        # Langflow Data object
        if hasattr(value, "data"):
            try:
                value = value.data
            except Exception:
                pass

        # JSON string fallback
        if isinstance(value, str):
            raw = value.strip()

            if not raw:
                return ""

            try:
                parsed = json.loads(raw)

                if isinstance(parsed, dict):
                    value = parsed
                else:
                    return raw

            except json.JSONDecodeError:
                return raw

        if not isinstance(value, dict):
            raise ValueError(
                "Current Email must be a Data/JSON object."
            )

        # Handle Langflow Data wrapper if present
        nested_data = value.get("data")

        if isinstance(nested_data, dict):
            value = nested_data

        sender_email = str(
            value.get("sender_email") or ""
        ).strip()

        sender_name = str(
            value.get("sender_name") or ""
        ).strip()

        subject = str(
            value.get("subject") or ""
        ).strip()

        body_text = str(
            value.get("body_text") or ""
        ).strip()

        if not body_text:
            raise ValueError(
                "Current Email body_text is empty."
            )

        lines = []

        # Keep sender identity because Company Knowledge may need it
        # for customer/account verification.
        if sender_name and sender_email:
            lines.append(
                f"From: {sender_name} <{sender_email}>"
            )

        elif sender_email:
            lines.append(
                f"From: {sender_email}"
            )

        elif sender_name:
            lines.append(
                f"From: {sender_name}"
            )

        # Only include subject when one actually exists.
        if subject:
            lines.append(
                f"Subject: {subject}"
            )

        # Separate metadata from actual customer content.
        if lines:
            lines.append("")

        lines.append(body_text)

        return "\n".join(lines).strip()

    @staticmethod
    def _normalise_text(
        value: Any,
    ) -> str:

        if isinstance(
            value,
            Message,
        ):
            return str(
                value.text or ""
            ).strip()

        if hasattr(
            value,
            "text",
        ):
            return str(
                value.text or ""
            ).strip()

        return str(
            value or ""
        ).strip()

    @staticmethod
    def _normalise_secret(
        value: Any,
    ) -> str:

        if value is None:
            return ""

        if hasattr(
            value,
            "get_secret_value",
        ):
            return str(
                value.get_secret_value()
                or ""
            ).strip()

        return str(
            value or ""
        ).strip()

    def _extract_exact_text(
        self,
        raw_result: dict[str, Any],
    ) -> str:

        structured = (
            raw_result.get(
                "structuredContent"
            )
            or raw_result.get(
                "structured_content"
            )
        )

        if isinstance(
            structured,
            dict,
        ):
            structured_result = structured.get(
                "result"
            )

            text = self._render_value(
                structured_result
            )

            if text:
                return text

        content = raw_result.get(
            "content"
        ) or []

        if isinstance(
            content,
            list,
        ):
            parts: list[str] = []

            for item in content:
                if not isinstance(
                    item,
                    dict,
                ):
                    continue

                text = item.get(
                    "text"
                )

                if (
                    isinstance(
                        text,
                        str,
                    )
                    and text.strip()
                ):
                    parts.append(
                        self._unwrap_json_text(
                            text
                        )
                    )

                    continue

                item_content = item.get(
                    "content"
                )

                if (
                    item_content
                    is not None
                ):
                    rendered = self._render_value(
                        item_content
                    )

                    if rendered:
                        parts.append(
                            rendered
                        )

            if parts:
                return "\n\n".join(
                    part
                    for part in parts
                    if part
                ).strip()

        return self._render_value(
            content
        )

    def _render_value(
        self,
        value: Any,
    ) -> str:

        if value is None:
            return ""

        if isinstance(
            value,
            str,
        ):
            return self._unwrap_json_text(
                value
            )

        if isinstance(
            value,
            list,
        ):
            parts = [
                self._render_value(
                    item
                )
                for item in value
            ]

            return "\n\n".join(
                part
                for part in parts
                if part
            ).strip()

        if isinstance(
            value,
            dict,
        ):
            item_type = str(
                value.get(
                    "type"
                )
                or ""
            ).strip().lower()

            if item_type in {
                "text",
                "markdown",
            }:
                content = value.get(
                    "content"
                )

                if content is None:
                    content = value.get(
                        "text"
                    )

                return self._render_value(
                    content
                )

            if (
                value.get(
                    "text"
                )
                is not None
            ):
                return self._render_value(
                    value[
                        "text"
                    ]
                )

            if (
                value.get(
                    "content"
                )
                is not None
            ):
                return self._render_value(
                    value[
                        "content"
                    ]
                )

            if (
                value.get(
                    "result"
                )
                is not None
            ):
                return self._render_value(
                    value[
                        "result"
                    ]
                )

            return json.dumps(
                value,
                ensure_ascii=False,
            )

        return str(
            value
        ).strip()

    def _unwrap_json_text(
        self,
        value: str,
    ) -> str:

        raw = str(
            value or ""
        ).strip()

        if not raw:
            return ""

        if not raw.startswith(
            ("{", "[")
        ):
            return raw

        try:
            parsed = json.loads(
                raw
            )

        except json.JSONDecodeError:
            return raw

        return self._render_value(
            parsed
        )

    @classmethod
    def _to_dict(
        cls,
        result: Any,
    ) -> dict[str, Any]:

        if isinstance(
            result,
            dict,
        ):
            return cls._dump_value(
                result
            )

        if hasattr(
            result,
            "model_dump",
        ):
            try:
                return result.model_dump(
                    by_alias=True
                )

            except TypeError:
                return result.model_dump()

        return {
            "content": cls._dump_value(
                getattr(
                    result,
                    "content",
                    [],
                )
            ),
            "structuredContent": cls._dump_value(
                getattr(
                    result,
                    "structured_content",
                    None,
                )
            ),
            "isError": bool(
                getattr(
                    result,
                    "is_error",
                    False,
                )
            ),
            "_meta": cls._dump_value(
                getattr(
                    result,
                    "meta",
                    None,
                )
            ),
        }

    @classmethod
    def _dump_value(
        cls,
        value: Any,
    ) -> Any:

        if hasattr(
            value,
            "model_dump",
        ):
            try:
                return value.model_dump(
                    by_alias=True
                )

            except TypeError:
                return value.model_dump()

        if isinstance(
            value,
            list,
        ):
            return [
                cls._dump_value(
                    item
                )
                for item in value
            ]

        if isinstance(
            value,
            dict,
        ):
            return {
                key: cls._dump_value(
                    item
                )
                for key, item
                in value.items()
            }

        return value

