class WebappReviewPOST(Component):
    display_name = "Webapp Review POST"
    description = (
        "POSTs the HITL review payload to the webapp "
        "for human review."
    )
    icon = "send"
    name = "WebappReviewPOST"

    inputs = [
        DataInput(
            name="review_payload",
            display_name="Review Payload",
            required=True,
        ),
        StrInput(
            name="endpoint_url",
            display_name="Webapp Endpoint URL",
            info="Example: https://example.invalid/customer-case",
            required=True,
        ),
        SecretStrInput(
            name="api_key",
            display_name="API Key",
            info="Optional API key for the webapp endpoint.",
            required=False,
        ),
        StrInput(
            name="api_key_header",
            display_name="API Key Header",
            value="Authorization",
            advanced=True,
        ),
        StrInput(
            name="api_key_prefix",
            display_name="API Key Prefix",
            value="Bearer",
            advanced=True,
        ),
        StrInput(
            name="extra_headers",
            display_name="Extra Headers",
            info='Optional JSON object. Example: {"x-source": "langflow"}',
            value="{}",
            advanced=True,
        ),
        IntInput(
            name="timeout",
            display_name="Timeout",
            value=30,
            advanced=True,
        ),
    ]

    outputs = [
        Output(
            name="response",
            display_name="Webapp Response",
            method="send_review",
        ),
    ]

    @staticmethod
    def _as_dict(value):
        if isinstance(value, Data):
            value = value.data

        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError:
                return {}

        return value if isinstance(value, dict) else {}

    @staticmethod
    def _secret_value(value):
        if value is None:
            return ""

        if hasattr(value, "get_secret_value"):
            return value.get_secret_value().strip()

        return str(value).strip()

    def _build_headers(self):
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
        }

        api_key = self._secret_value(
            self.api_key
        )

        if api_key:
            header_name = str(
                self.api_key_header or "Authorization"
            ).strip()

            prefix = str(
                self.api_key_prefix or ""
            ).strip()

            if prefix:
                headers[header_name] = (
                    f"{prefix} {api_key}"
                )
            else:
                headers[header_name] = api_key

        extra_headers_raw = str(
            self.extra_headers or "{}"
        ).strip()

        if extra_headers_raw:
            try:
                extra_headers = json.loads(
                    extra_headers_raw
                )
            except json.JSONDecodeError as exc:
                raise ValueError(
                    "EXTRA_HEADERS_INVALID: "
                    "Extra Headers must be valid JSON."
                ) from exc

            if not isinstance(extra_headers, dict):
                raise ValueError(
                    "EXTRA_HEADERS_INVALID: "
                    "Extra Headers must be a JSON object."
                )

            for key, value in extra_headers.items():
                headers[str(key)] = str(value)

        return headers

    async def send_review(self) -> Data:
        payload = self._as_dict(
            self.review_payload
        )

        if not payload:
            raise ValueError(
                "REVIEW_PAYLOAD_INVALID: "
                "Review Payload is required."
            )

        endpoint = str(
            self.endpoint_url or ""
        ).strip()

        if not endpoint:
            raise ValueError(
                "WEBAPP_ENDPOINT_INVALID: "
                "Webapp Endpoint URL is required."
            )

        headers = self._build_headers()

        try:
            async with httpx.AsyncClient(
                timeout=float(self.timeout or 30)
            ) as client:

                response = await client.post(
                    endpoint,
                    json=payload,
                    headers=headers,
                )

        except httpx.RequestError as exc:
            raise ValueError(
                "WEBAPP_REQUEST_FAILED: "
                f"{str(exc)}"
            ) from exc

        response_text = (
            response.text or ""
        ).strip()

        try:
            response_body = (
                response.json()
                if response_text
                else {}
            )
        except Exception:
            response_body = response_text

        if not 200 <= response.status_code < 300:
            raise ValueError(
                "WEBAPP_POST_FAILED: "
                f"HTTP {response.status_code} - "
                f"{response_text}"
            )

        self.status = (
            f"REVIEW_SUBMITTED | "
            f"HTTP {response.status_code}"
        )

        return Data(
            data={
                "success": True,
                "status_code": response.status_code,
                "response": response_body,
                "message_id": payload.get(
                    "message_id"
                ),
                "conversation_id": payload.get(
                    "conversation_id"
                ),
                "review_status": payload.get(
                    "review_status"
                ),
            }
        )

