class Company KnowledgeSessionIDBuilder(Component):
    display_name = "Company Knowledge Session ID Builder"
    description = (
        "Builds a stable Company Knowledge session ID for an Outlook email thread "
        "using connected_account_id and conversation_id."
    )
    icon = "link"
    name = "Company KnowledgeSessionIDBuilder"

    inputs = [
        DataInput(
            name="email_data",
            display_name="Email Data",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="session_id",
            display_name="Session ID",
            method="build_session_id",
        ),
    ]

    @staticmethod
    def _as_dict(value):
        if isinstance(value, Data):
            value = value.data

        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError:
                return {}

        return value if isinstance(value, dict) else {}

    @staticmethod
    def _find_value(value, key):
        if isinstance(value, dict):
            if value.get(key) not in (None, ""):
                return value.get(key)

            for nested in value.values():
                found = Company KnowledgeSessionIDBuilder._find_value(
                    nested,
                    key,
                )

                if found not in (None, ""):
                    return found

        elif isinstance(value, list):
            for item in value:
                found = Company KnowledgeSessionIDBuilder._find_value(
                    item,
                    key,
                )

                if found not in (None, ""):
                    return found

        return None

    def build_session_id(self) -> Message:
        data = self._as_dict(
            self.email_data
        )

        if not data:
            raise ValueError(
                "SESSION_INPUT_INVALID: "
                "Email Data is required."
            )

        conversation_id = self._find_value(
            data,
            "conversation_id",
        )

        connected_account_id = self._find_value(
            data,
            "connected_account_id",
        )

        if not conversation_id:
            raise ValueError(
                "SESSION_INPUT_INVALID: "
                "'conversation_id' is required."
            )

        # connected_account_id is used to namespace sessions
        # when available.
        namespace = (
            f"{connected_account_id}|{conversation_id}"
            if connected_account_id
            else str(conversation_id)
        )

        digest = hashlib.sha256(
            namespace.encode("utf-8")
        ).hexdigest()[:32]

        session_id = (
            f"outlook-thread-{digest}"
        )

        self.status = session_id

        return Message(
            text=session_id
        )

import re

from lfx.custom.custom_component.component import Component
from lfx.io import MessageInput, Output
