class Company KnowledgeResponseParser(Component):
    display_name = "Company Knowledge Response Parser"
    description = (
        "Parses the structured Company Knowledge investigation evidence "
        "for downstream email drafting and human review."
    )
    icon = "braces"
    name = "Company KnowledgeResponseParser"

    inputs = [
        MessageInput(
            name="company-knowledge_response",
            display_name="Company Knowledge Response",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="parsed_result",
            display_name="Parsed Company Knowledge Evidence",
            method="parse_response",
        ),
    ]

    @staticmethod
    def _extract_text(value):
        if isinstance(value, Message):
            return str(value.text or "").strip()

        if hasattr(value, "text"):
            return str(value.text or "").strip()

        return str(value or "").strip()

    @staticmethod
    def _strip_code_fences(text):
        text = str(text or "").strip()

        text = re.sub(
            r"^```(?:markdown|md|text)?\s*",
            "",
            text,
            flags=re.IGNORECASE,
        )

        text = re.sub(
            r"\s*```$",
            "",
            text,
        )

        return text.strip()

    @staticmethod
    def _trim_after_end(text):
        """
        Company Knowledge may append tables/download links after END.
        Everything after the standalone END marker is ignored.
        """
        match = re.search(
            r"(?im)^\s*END\s*$",
            text,
        )

        if match:
            return text[:match.start()].strip()

        return text.strip()

    @staticmethod
    def _extract_intent(text):
        match = re.search(
            r"(?im)^Intent\s*:\s*([A-Z][A-Z0-9_]*?)\s*$",
            text,
        )

        if not match:
            raise ValueError(
                "INTUGLE_RESPONSE_INVALID: "
                "'Intent:' line is required."
            )

        intent = match.group(1).strip()

        if not re.fullmatch(
            r"[A-Z][A-Z0-9_]*",
            intent,
        ):
            raise ValueError(
                "INTUGLE_RESPONSE_INVALID: "
                "Intent must be UPPERCASE_SNAKE_CASE."
            )

        return intent

    @staticmethod
    def _has_heading(text, heading):
        pattern = (
            r"(?im)^###\s+"
            + re.escape(heading)
            + r"\s*$"
        )

        return bool(
            re.search(pattern, text)
        )

    @staticmethod
    def _extract_section(
        text,
        heading,
        next_heading=None,
    ):
        start_pattern = (
            r"(?im)^###\s+"
            + re.escape(heading)
            + r"\s*$"
        )

        start_match = re.search(
            start_pattern,
            text,
        )

        if not start_match:
            return ""

        start = start_match.end()

        if next_heading:
            end_pattern = (
                r"(?im)^###\s+"
                + re.escape(next_heading)
                + r"\s*$"
            )

            end_match = re.search(
                end_pattern,
                text[start:],
            )

            if end_match:
                end = (
                    start
                    + end_match.start()
                )
            else:
                end = len(text)

        else:
            end = len(text)

        return text[start:end].strip()

    @staticmethod
    def _parse_bullets(value):
        value = str(value or "").strip()

        if not value:
            return []

        if value.lower() in {
            "none",
            "- none",
            "n/a",
            "- n/a",
        }:
            return []

        items = []
        current = []

        for raw_line in value.splitlines():
            line = raw_line.strip()

            bullet = re.match(
                r"^[-*]\s+(.*)$",
                line,
            )

            if bullet:
                if current:
                    item = " ".join(
                        current
                    ).strip()

                    if item:
                        items.append(item)

                current = [
                    bullet.group(1).strip()
                ]

            elif line and current:
                current.append(line)

        if current:
            item = " ".join(
                current
            ).strip()

            if item:
                items.append(item)

        # Fallback if Company Knowledge returns plain text
        # instead of bullets.
        if not items and value:
            cleaned = value.strip()

            if cleaned.lower() not in {
                "none",
                "n/a",
            }:
                items.append(cleaned)

        return items

    @staticmethod
    def _parse_escalation(value):
        value = str(value or "").strip()

        status_match = re.search(
            r"(?im)^\s*[-*]?\s*"
            r"Needs\s+Escalation\s*:\s*"
            r"(YES|NO|TRUE|FALSE)\s*$",
            value,
        )

        if not status_match:
            raise ValueError(
                "INTUGLE_RESPONSE_INVALID: "
                "'Needs Escalation' value is required."
            )

        status = (
            status_match.group(1)
            .strip()
            .upper()
        )

        needs_escalation = (
            status in {
                "YES",
                "TRUE",
            }
        )

        reason_match = re.search(
            r"(?ims)^\s*[-*]?\s*"
            r"Reason\s*:\s*(.+?)"
            r"(?=\n\s*[-*]\s*|\Z)",
            value,
        )

        escalation_reason = ""

        if reason_match:
            escalation_reason = (
                reason_match.group(1)
                .strip()
            )

        if (
            needs_escalation
            and not escalation_reason
        ):
            raise ValueError(
                "INTUGLE_RESPONSE_INVALID: "
                "Escalation reason is required "
                "when Needs Escalation is YES."
            )

        return (
            needs_escalation,
            escalation_reason,
        )

    def parse_response(self) -> Data:
        raw_text = self._extract_text(
            self.company-knowledge_response
        )

        if not raw_text:
            raise ValueError(
                "INTUGLE_RESPONSE_INVALID: "
                "Company Knowledge response is empty."
            )

        raw_text = self._strip_code_fences(
            raw_text
        )

        # Remove anything Company Knowledge appends after END,
        # including transaction tables/download links.
        raw_text = self._trim_after_end(
            raw_text
        )

        if not re.search(
            r"(?im)^##\s+Investigation Evidence\s*$",
            raw_text,
        ):
            raise ValueError(
                "INTUGLE_RESPONSE_INVALID: "
                "'## Investigation Evidence' "
                "section is required."
            )

        # Extract the new Intent line.
        intent = self._extract_intent(
            raw_text
        )

        required_headings = [
            "Verified Facts",
            "Unverified Inferences",
            "Customer-Safe Facts",
            "Missing Information",
            "Conflicts",
            "Escalation",
            "Summary",
        ]

        for heading in required_headings:
            if not self._has_heading(
                raw_text,
                heading,
            ):
                raise ValueError(
                    "INTUGLE_RESPONSE_INVALID: "
                    f"'### {heading}' section "
                    "is required."
                )

        verified_text = self._extract_section(
            raw_text,
            "Verified Facts",
            "Unverified Inferences",
        )

        inference_text = self._extract_section(
            raw_text,
            "Unverified Inferences",
            "Customer-Safe Facts",
        )

        safe_text = self._extract_section(
            raw_text,
            "Customer-Safe Facts",
            "Missing Information",
        )

        missing_text = self._extract_section(
            raw_text,
            "Missing Information",
            "Conflicts",
        )

        conflicts_text = self._extract_section(
            raw_text,
            "Conflicts",
            "Escalation",
        )

        escalation_text = self._extract_section(
            raw_text,
            "Escalation",
            "Summary",
        )

        summary = self._extract_section(
            raw_text,
            "Summary",
        )

        if not summary:
            raise ValueError(
                "INTUGLE_RESPONSE_INVALID: "
                "'### Summary' cannot be empty."
            )

        (
            needs_escalation,
            escalation_reason,
        ) = self._parse_escalation(
            escalation_text
        )

        evidence = {
            "verified_facts": self._parse_bullets(
                verified_text
            ),
            "unverified_inferences": self._parse_bullets(
                inference_text
            ),
            "customer_safe_facts": self._parse_bullets(
                safe_text
            ),
            "missing_information": self._parse_bullets(
                missing_text
            ),
            "conflicts": self._parse_bullets(
                conflicts_text
            ),
            "needs_escalation": needs_escalation,
            "escalation_reason": escalation_reason,
            "summary": summary,
        }

        parsed = {
            "intent": intent,
            "evidence": evidence,
        }

        self.status = (
            f"INTUGLE_EVIDENCE_READY | {intent}"
            + (
                " | ESCALATION_FLAGGED"
                if needs_escalation
                else ""
            )
        )

        return Data(
            data=parsed
        )

