class EmailDraftInputBuilder(Component):
    display_name = "Email Draft Input Builder"
    description = (
        "Combines Outlook thread context and parsed Company Knowledge "
        "investigation evidence for the email drafting LLM."
    )
    icon = "mail"
    name = "EmailDraftInputBuilder"

    inputs = [
        DataInput(
            name="thread_context",
            display_name="Thread Context",
            required=True,
        ),
        DataInput(
            name="investigation_result",
            display_name="Parsed Company Knowledge Evidence",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="llm_input",
            display_name="LLM Input",
            method="build_input",
        ),
    ]

    @staticmethod
    def _as_dict(value):
        if isinstance(value, Data):
            value = value.data

        if hasattr(value, "data"):
            try:
                value = value.data
            except Exception:
                pass

        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError:
                return {}

        return value if isinstance(value, dict) else {}

    @staticmethod
    def _clean(value):
        if value is None:
            return ""

        return str(value).strip()

    def build_input(self) -> Message:
        thread = self._as_dict(
            self.thread_context
        )

        investigation = self._as_dict(
            self.investigation_result
        )

        if not thread:
            raise ValueError(
                "THREAD_CONTEXT_INVALID: "
                "Thread Context is required."
            )

        if not investigation:
            raise ValueError(
                "INVESTIGATION_RESULT_INVALID: "
                "Parsed Company Knowledge Evidence is required."
            )

        # Current parser returns the investigation
        # under the "evidence" key.
        evidence = investigation.get(
            "evidence",
            investigation,
        )

        if not isinstance(evidence, dict):
            raise ValueError(
                "INVESTIGATION_RESULT_INVALID: "
                "'evidence' must be an object."
            )

        # Keep only customer-conversation fields
        # useful to the drafting LLM.
        thread_context = {
            "sender_email": self._clean(
                thread.get("sender_email")
            ),
            "sender_name": self._clean(
                thread.get("sender_name")
            ),
            "subject": self._clean(
                thread.get("subject")
            ),
            "body_text": self._clean(
                thread.get("body_text")
            ),
            "history_status": thread.get(
                "history_status"
            ),
            "prior_message_count": thread.get(
                "prior_message_count",
                0,
            ),
            "messages": thread.get(
                "messages",
                [],
            ),
        }

        investigation_evidence = {
            "verified_facts": evidence.get(
                "verified_facts",
                [],
            ),
            "unverified_inferences": evidence.get(
                "unverified_inferences",
                [],
            ),
            "customer_safe_facts": evidence.get(
                "customer_safe_facts",
                [],
            ),
            "missing_information": evidence.get(
                "missing_information",
                [],
            ),
            "conflicts": evidence.get(
                "conflicts",
                [],
            ),
            "needs_escalation": evidence.get(
                "needs_escalation",
                False,
            ),
            "escalation_reason": self._clean(
                evidence.get(
                    "escalation_reason"
                )
            ),
            "summary": self._clean(
                evidence.get("summary")
            ),
        }

        payload = {
            "thread_context": thread_context,
            "investigation_evidence": (
                investigation_evidence
            ),
        }

        text = json.dumps(
            payload,
            ensure_ascii=False,
            indent=2,
        )

        self.status = (
            "EMAIL_DRAFT_INPUT_READY"
        )

        return Message(
            text=text,
            sender="Machine",
            sender_name="EmailDraftInputBuilder",
        )

