            required=True,
        ),
    ]

    outputs = [
        Output(
            name="review_payload",
            display_name="Review Payload",
            method="build_payload",
        ),
    ]

    @staticmethod
    def _as_dict(value):
        if isinstance(value, Data):
            value = value.data

        if hasattr(value, "data"):
            try:
                value = value.data
            except Exception:
                pass

        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError:
                return {}

        return value if isinstance(value, dict) else {}

    @staticmethod
    def _clean(value):
        if value is None:
            return ""

        return str(value).strip()

    @staticmethod
    def _as_list(value):
        if isinstance(value, list):
            return value

        if value is None:
            return []

        cleaned = str(value).strip()

        return [cleaned] if cleaned else []

    def build_payload(self) -> Data:
        thread = self._as_dict(
            self.thread_context
        )

        company-knowledge = self._as_dict(
            self.company-knowledge_result
        )

        draft = self._as_dict(
            self.draft_result
        )

        if not thread:
            raise ValueError(
                "THREAD_CONTEXT_INVALID: "
                "Thread Context is required."
            )

        if not company-knowledge:
            raise ValueError(
                "INTUGLE_RESULT_INVALID: "
                "Parsed Company Knowledge Evidence is required."
            )

        if not draft:
            raise ValueError(
                "DRAFT_RESULT_INVALID: "
                "Parsed Email Draft is required."
            )

        evidence = company-knowledge.get(
            "evidence",
            company-knowledge,
        )

        if not isinstance(evidence, dict):
            raise ValueError(
                "INTUGLE_RESULT_INVALID: "
                "'evidence' must be an object."
            )

        intent = self._clean(
            company-knowledge.get("intent")
        )

        if not intent:
            raise ValueError(
                "INTUGLE_RESULT_INVALID: "
                "'intent' is required."
            )

