            thread.get("subject")
        )

        received_at = self._clean(
            thread.get("received_at")
        )

        current_email = self._clean(
            thread.get("body_text")
        )

        if not message_id:
            raise ValueError(
                "THREAD_CONTEXT_INVALID: "
                "'message_id' is required."
            )

        if not conversation_id:
            raise ValueError(
                "THREAD_CONTEXT_INVALID: "
                "'conversation_id' is required."
            )

        if not sender_email:
            raise ValueError(
                "THREAD_CONTEXT_INVALID: "
                "'sender_email' is required."
            )

        needs_escalation = evidence.get(
            "needs_escalation",
            False,
        )

        if not isinstance(
            needs_escalation,
            bool,
        ):
            raise ValueError(
                "INTUGLE_RESULT_INVALID: "
                "'needs_escalation' must be true or false."
            )

        escalation_reason = self._clean(
            evidence.get(
                "escalation_reason"
            )
        )

        if (
            needs_escalation
            and not escalation_reason
        ):
            raise ValueError(
                "INTUGLE_RESULT_INVALID: "
                "'escalation_reason' is required "
                "when 'needs_escalation' is true."
            )

        draft_subject = self._clean(
            draft.get("subject")
        )

        draft_body = self._clean(
            draft.get("body")
        )

        draft_status = self._clean(
            draft.get("draft_status")
        ).upper()

        if not draft_subject:
            raise ValueError(
                "DRAFT_RESULT_INVALID: "
                "'subject' is required."
            )

        if not draft_body:
            raise ValueError(
                "DRAFT_RESULT_INVALID: "
                "'body' is required."
            )

        if (
            draft_status
            not in self.VALID_DRAFT_STATUSES
        ):
            raise ValueError(
                "DRAFT_RESULT_INVALID: "
                f"Unsupported draft_status "
                f"'{draft_status}'."
            )

        payload = {
            # Required identifiers.
            "message_id": message_id,
            "conversation_id": conversation_id,
            "connected_account_id": connected_account_id,

            # Intent.
            "intent": intent,

            # Retained for compatibility with the existing webapp.
            "understanding": {
                "primary_intent": intent,
            },

            # Existing webapp-compatible sender fields.
            "sender_email": sender_email,
            "sender_name": sender_name,
            "subject": subject,
            "received_at": received_at,
            "current_email": current_email,

            # Structured customer object for reviewer UI.
            "customer": {
                "name": sender_name,
                "email": sender_email,
            },

            # Full conversation context.
            "thread_context": {
                "subject": subject,
                "received_at": received_at,
                "body_text": current_email,
                "history_status": thread.get(
                    "history_status"
                ),
                "prior_message_count": thread.get(
                    "prior_message_count",
                    0,
                ),
                "messages": thread.get(
                    "messages",
                    [],
                ),
            },

            # Structured Company Knowledge investigation output.
            "investigation_evidence": {
                "verified_facts": self._as_list(
                    evidence.get(
                        "verified_facts"
                    )
                ),
                "unverified_inferences": self._as_list(
                    evidence.get(
                        "unverified_inferences"
                    )
                ),
                "customer_safe_facts": self._as_list(
                    evidence.get(
                        "customer_safe_facts"
                    )
                ),
                "missing_information": self._as_list(
                    evidence.get(
                        "missing_information"
                    )
                ),
                "conflicts": self._as_list(
                    evidence.get(
                        "conflicts"
                    )
                ),
                "needs_escalation": needs_escalation,
                "escalation_reason": escalation_reason,
                "summary": self._clean(
                    evidence.get(
                        "summary"
                    )
                ),
            },

            # Separate email drafting LLM output.
            "draft": {
                "subject": draft_subject,
                "body": draft_body,
                "draft_status": draft_status,
            },

            "review_status": (
                "AWAITING_HUMAN_REVIEW"
            ),
        }

        self.status = (
            f"AWAITING_HUMAN_REVIEW | {intent}"
            + (
                " | ESCALATION_FLAGGED"
                if needs_escalation
                else ""
            )
        )

        return Data(
            data=payload
        )

import json
import re

from lfx.custom.custom_component.component import Component
from lfx.io import MessageInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


class EmailDraftParser(Component):
    display_name = "Email Draft Parser"
    description = (
        "Parses and validates the customer email draft "
        "returned by the Email Drafting LLM."
    )
    icon = "mail-check"
    name = "EmailDraftParser"

    VALID_DRAFT_STATUSES = {
        "READY",
        "NEEDS_CLARIFICATION",
        "ESCALATE",
    }

    inputs = [
        MessageInput(
            name="draft_response",
            display_name="Email Draft Response",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="parsed_draft",
            display_name="Parsed Email Draft",
            method="parse_draft",
        ),
    ]

    @staticmethod
    def _extract_text(value):
        if isinstance(value, Message):
            return str(value.text or "").strip()

        if hasattr(value, "text"):
            return str(value.text or "").strip()

        return str(value or "").strip()

    @staticmethod
    def _strip_code_fences(text):
        text = str(text or "").strip()

        text = re.sub(
            r"^```(?:json)?\s*",
            "",
            text,
            flags=re.IGNORECASE,
        )

        text = re.sub(
            r"\s*```$",
            "",
            text,
        )

        return text.strip()

    @staticmethod
    def _clean(value):
        if value is None:
            return ""

        return str(value).strip()

    def parse_draft(self) -> Data:
        raw_text = self._extract_text(
            self.draft_response
        )

        if not raw_text:
            raise ValueError(
                "EMAIL_DRAFT_INVALID: "
                "Email drafting LLM response is empty."
            )

        raw_text = self._strip_code_fences(
            raw_text
        )

        try:
            result = json.loads(
                raw_text
            )

        except json.JSONDecodeError as exc:
            raise ValueError(
                "EMAIL_DRAFT_INVALID: "
                f"Response must be valid JSON: {exc}"
            ) from exc

        if not isinstance(result, dict):
            raise ValueError(
                "EMAIL_DRAFT_INVALID: "
                "Top-level response must be a JSON object."
            )

        subject = self._clean(
            result.get("subject")
        )

        body = self._clean(
            result.get("body")
        )

        draft_status = self._clean(
            result.get("draft_status")
        ).upper()

        if not subject:
            raise ValueError(
                "EMAIL_DRAFT_INVALID: "
                "'subject' is required."
            )

        if not body:
            raise ValueError(
                "EMAIL_DRAFT_INVALID: "
                "'body' is required."
            )

        if (
            draft_status
            not in self.VALID_DRAFT_STATUSES
        ):
            raise ValueError(
                "EMAIL_DRAFT_INVALID: "
                f"Unsupported draft_status "
                f"'{draft_status}'."
            )

        parsed = {
            "subject": subject,
            "body": body,
            "draft_status": draft_status,
        }

        self.status = (
            f"EMAIL_DRAFT_READY | "
            f"{draft_status}"
        )

        return Data(
            data=parsed
        )
